const $=s=>document.querySelector(s);let style='电影感',mode='text',running=false;let works=[];try{works=JSON.parse(localStorage.getItem('yunying-works')||'[]')}catch{}const ideas=[{title:'山海之间，去感受自由',text:'航拍视角掠过云雾缭绕的青绿色山脉，阳光穿过云层洒在山谷，镜头缓慢向前，壮阔自然风光，电影感。',img:'photo-1464822759023-fed622ff2c3b',tag:'自然风光',color:'#658b76'},{title:'把平凡，拍成电影',text:'午后阳光洒进复古咖啡馆，一杯拿铁升起轻柔的热气，窗外行人缓缓走过，镜头缓慢推进，温暖胶片质感。',img:'photo-1445116572660-236099ec97a0',tag:'生活美学',color:'#927253'},{title:'潜入一场蓝色的梦',text:'一只鲸鱼在深蓝色的海洋中缓缓游动，阳光从水面投下光柱，水中细小气泡闪烁，梦幻而宁静，广角镜头。',img:'photo-1530053969600-caed2596d242',tag:'梦幻世界',color:'#236779'},{title:'未来，正在此刻发生',text:'雨夜的未来城市，霓虹灯倒映在湿润的街道上，一个身影撑着透明雨伞向远处走去，镜头低机位跟随，赛博朋克风格。',img:'photo-1519608487953-e999c86e7455',tag:'未来城市',color:'#61516e'}];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}function setPrompt(t){$('#prompt').value=t;$('#chars').textContent=t.length+' / 1200';$('#prompt').focus()}function showView(v){$('#createView').hidden=v!=='create';$('#libraryView').hidden=v!=='library';$('#inspirations').hidden=v==='library';$('#title').innerHTML=v==='library'?'留住每一次，<em>灵光乍现。</em>':v==='inspire'?'好灵感，<em>从这里开始。</em>':'让灵感，<em>动起来。</em>';$('#crumb').textContent=v==='library'?'我的作品':v==='inspire'?'灵感广场':'视频生成';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='library')renderLibrary()}
function renderCards(){ $('#cards').innerHTML=ideas.map((x,i)=>`<button class="card" data-idea="${i}"><div class="thumb" style="background-color:${x.color};background-image:linear-gradient(0deg,#102c3250,transparent),url(https://images.unsplash.com/${x.img}?auto=format&fit=crop&w=700&q=80)"><span class="badge">${x.tag}</span></div><div class="card-body"><strong>${x.title}</strong><p>点击使用同款灵感 <span style="float:right">✧ 立即创作</span></p></div></button>`).join('');document.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>{showView('create');setPrompt(ideas[+b.dataset.idea].text);window.scrollTo({top:0,behavior:'smooth'})})}renderCards();$('#count').textContent=works.length;
$('#prompt').oninput=()=>$('#chars').textContent=$('#prompt').value.length+' / 1200';$('#random').onclick=()=>setPrompt(ideas[Math.floor(Math.random()*ideas.length)].text);$('#more').onclick=()=>{ideas.push(ideas.shift());renderCards();toast('新一组灵感已就位')};document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#new').onclick=()=>{showView('create');setPrompt('')};document.querySelectorAll('.style').forEach(b=>b.onclick=()=>{style=b.dataset.style;document.querySelectorAll('.style').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$('#uploadBox').hidden=mode!=='image';document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b))});$('#imageInput').onchange=e=>{let f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)return toast('请选择 10MB 以内的图片');if(!f.type.startsWith('image/'))return toast('请选择图片文件');let r=new FileReader;r.onload=()=>{$('#imagePreview').src=r.result;$('#imagePreview').hidden=false};r.readAsDataURL(f)};
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}$('#closeModal').onclick=()=>$('#modal').close();$('#help').onclick=$('#about').onclick=()=>modal('<h2>让灵感动起来 ✦</h2><p>1. 写下画面描述，或选择下方灵感卡片。<br>2. 选择风格、比例、时长和清晰度。<br>3. 点击生成，体验任务进度与作品管理。</p><p>这是可交互的前端原型，预览为动态占位画面，尚未接入视频生成模型。作品记录保存在当前浏览器，可下载创作参数 JSON。</p>');
$('#generate').onclick=()=>{if(running)return;const prompt=$('#prompt').value.trim();if(!prompt){toast('先写下一点画面灵感吧');$('#prompt').focus();return}if(mode==='image'&&!$('#imageInput').files.length)return toast('请先上传一张参考图片');running=true;$('#generate').disabled=true;$('#previewStatus').textContent='正在模拟生成';$('#previewArea').innerHTML='<div class="orb spin"><span>✦</span></div><h2 id="phase">正在理解你的灵感…</h2><div class="progress"><div id="bar" style="width:0%"></div></div><p id="percent">0% · 演示任务</p>';let n=0;let timer=setInterval(()=>{n=Math.min(100,n+4);$('#bar').style.width=n+'%';$('#percent').textContent=n+'% · 演示任务';$('#phase').textContent=n<30?'正在理解你的灵感…':n<65?'正在构建画面与运镜…':'正在完成画面细节…';if(n===100){clearInterval(timer);const w={id:Date.now(),prompt,style,ratio:$('#ratio').value,duration:$('#duration').value,quality:$('#quality').value,mode,date:new Date().toLocaleString('zh-CN')};works.unshift(w);try{localStorage.setItem('yunying-works',JSON.stringify(works))}catch{toast('浏览器存储不可用，作品仅保留在本次会话')}$('#count').textContent=works.length;showResult(w);running=false;$('#generate').disabled=false}},180)};
function download(w){const url=URL.createObjectURL(new Blob([JSON.stringify(w,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='云映-创作参数-'+w.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function showResult(w){$('#previewStatus').textContent='演示任务已完成';$('#previewArea').innerHTML='<div class="result-art"><span>✦</span><small>动态画面演示 · 非 AI 生成视频</small></div><h2>灵感已呈现</h2><p id="resultMeta"></p><div class="result-actions"><button id="saveParams">↓ 下载创作参数</button><button id="reuse">↻ 再创作</button></div>';const r=w.ratio.startsWith('9')?'9/16':w.ratio.startsWith('1:1')?'1':'16/9';$('#previewArea .result-art').style.aspectRatio=r;$('#previewArea .result-art').style.maxHeight='300px';$('#resultMeta').textContent=[w.style,w.ratio,w.duration,w.quality].join(' · ');$('#saveParams').onclick=()=>download(w);$('#reuse').onclick=()=>setPrompt(w.prompt)}function renderLibrary(){const el=$('#library');el.innerHTML='';if(!works.length){el.innerHTML='<p style="color:#8b9991;padding:45px 0">还没有作品，去写下你的第一个灵感吧。</p>';return}works.forEach(w=>{let card=document.createElement('button');card.className='card';card.innerHTML='<div class="result-art" style="border-radius:0;height:150px"><span>✦</span><small>前端演示作品</small></div><div class="card-body"><strong></strong><p></p></div>';card.querySelector('strong').textContent=w.prompt.slice(0,24)+(w.prompt.length>24?'…':'');card.querySelector('p').textContent=w.style+' · '+w.duration+' · '+w.quality;card.onclick=()=>{showView('create');setPrompt(w.prompt);showResult(w)};el.append(card)})}

