let kind='video',activeTask=null,pollTimer=null;
const models={video:['doubao-seedance-2-0-260128','doubao-seedance-2-0-fast-260128','doubao-seedance-1-5-pro-251215','doubao-seedance-1-0-pro-250528','doubao-seedance-2-0-mini-260615','doubao-seedance-2-5-260628'],image:['gpt-image-2','gpt-image-1','gpt-image-2.5','gemini-2.5-flash-image','gemini-3-pro-image-preview','doubao-seedream-5-0-pro-260628'],music:['chirp-v4','chirp-v3','chirp-v3-5','chirp-v4-5','chirp-v4-5+','chirp-v5','suno-v3']};
