const statusLine=document.createElement('p');statusLine.className='connection-note';$('.tabs').after(statusLine);
function setKind(k){kind=k;document.querySelectorAll('[data-kind]').forEach(b=>b.classList.toggle('selected',b.dataset.kind===k));$('#model').replaceChildren(...models[k].map(m=>new Option(m,m)));$('#duration').closest('label').hidden=k!=='video';$('#ratio').closest('label').hidden=k!=='video';$('.styles').hidden=k==='music';$('.spaced').hidden=k==='music';$('#generate').textContent='✦ 生成'+({video:'视频',image:'图片',music:'音乐'}[k]);$('#prompt').placeholder=k==='music'?'描述音乐的风格、情绪、乐器与人声，例如：轻快的中文流行音乐，温暖女声，原声吉他与钢琴，适合夏日旅行。':'描述你想生成的画面、主体、场景与风格…';$('#crumb').textContent={video:'视频生成',image:'图片生成',music:'音乐生成'}[k]}
document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{if(running)return toast('请等待当前请求结束');setKind(b.dataset.kind)});setKind('video');
async function api(url,options){const r=await fetch(url,options);let data;try{data=await r.json()}catch{throw new Error('请使用本机后端地址打开页面，而非直接打开 HTML 文件')}if(!r.ok){const e=new Error(data.error||'API 请求失败');e.status=r.status;throw e}return data}
async function check(){if(location.protocol==='file:'){statusLine.textContent='请先运行 start.ps1，再打开 http://127.0.0.1:5173';$('.demo').textContent='● 需启动后端';return}try{const c=await api('/api/config');$('.demo').textContent=c.configured?'● API 已配置':'● 等待配置密钥';statusLine.textContent=(c.configured?'已连接云端服务，关机后仍可访问。':'云端密钥尚未配置。')+(c.musicPolling?'':'音乐查询路径待配置；可提交任务并查看原始响应。')}catch(e){statusLine.textContent=e.message}}
check();
$('#help').onclick=$('#about').onclick=()=>modal('<h2>连接创作 API</h2><p>运行项目中的 start.ps1，在本机隐藏输入 API Key，然后访问 http://127.0.0.1:5173。密钥仅供后端读取，不会写入前端或作品历史。</p><p>视频使用 Seedance 任务接口；图片使用 images/generations；音乐使用 Suno generate。模型列表来自你提供的清单，实际可用性以平台账户为准。其他厂商的视频协议未提供，尚未接入。</p><p>音乐 getState 的路径和响应格式尚未核实；请依平台文档配置 SUNO_STATE_PATH（使用 {id} 占位符）。结果出现音频地址后可播放和打开下载。图片默认输出 1024×1024。画面风格会加入提示词。</p>');
function unwrap(data){return data.data&&typeof data.data==='object'&&!Array.isArray(data.data)?data.data:data}
function taskId(data){const d=unwrap(data);return d.id||d.task_id||d.taskId||null}
function mediaItems(data,k){const found=[];const walk=(x,depth=0)=>{if(!x||depth>8)return;if(Array.isArray(x)){x.forEach(v=>walk(v,depth+1));return}if(typeof x!=='object')return;for(const [key,v] of Object.entries(x)){if(typeof v==='string'&&((k==='image'&&['url','image_url'].includes(key))||(k==='video'&&['video_url','videoUrl'].includes(key))||(k==='music'&&['audio_url','audioUrl'].includes(key)))){try{let u=new URL(v);if(u.protocol==='https:'||u.protocol==='http:')found.push(u.href)}catch{}}else if(k==='image'&&key==='b64_json'&&typeof v==='string'&&/^[A-Za-z0-9+/=\r\n]+$/.test(v)){found.push('data:image/png;base64,'+v)}else if(typeof v==='object')walk(v,depth+1)}};walk(data);return [...new Set(found)]}
function busy(text){$('#previewArea').replaceChildren();const h=document.createElement('h2');h.textContent=text;$('#previewArea').append(h);$('#previewStatus').textContent=text}
function rawPanel(data){const details=document.createElement('details');details.className='raw-result';const summary=document.createElement('summary');summary.textContent='查看平台原始响应';const pre=document.createElement('pre');pre.textContent=JSON.stringify(data,null,2);details.append(summary,pre);$('#previewArea').append(details)}
function record(w){works.unshift(w);try{localStorage.setItem('yunying-works',JSON.stringify(works))}catch{toast('作品过大，无法保存到浏览器历史')}$('#count').textContent=works.length}
const oldShowResult=showResult;
showResult=function(w){if(!w.kind)return oldShowResult(w);$('#previewArea').replaceChildren();$('#previewStatus').textContent='生成完成';w.media.forEach(url=>{const el=document.createElement(w.kind==='image'?'img':w.kind==='music'?'audio':'video');el.src=url;el.className='generated-media';if(w.kind!=='image'){el.controls=true;el.preload='metadata'}else el.alt=w.prompt;$('#previewArea').append(el);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=w.kind==='image'?'打开 / 保存图片 ↗':w.kind==='music'?'打开 / 下载音频 ↗':'打开 / 下载视频 ↗';if(url.startsWith('data:'))a.download='云映.png';a.className='media-link';$('#previewArea').append(a)});const p=document.createElement('p');p.textContent=w.prompt;$('#previewArea').append(p);const b=document.createElement('button');b.textContent='使用此描述再次创作';b.className='media-link';b.onclick=()=>{setKind(w.kind);setPrompt(w.prompt)};$('#previewArea').append(b)};
const oldLibrary=renderLibrary;renderLibrary=function(){oldLibrary();document.querySelectorAll('#library .card').forEach((card,i)=>{const w=works[i];if(!w?.kind)return;card.querySelector('small').textContent={video:'视频',image:'图片',music:'音乐'}[w.kind]+' · API 作品';card.querySelector('p').textContent=w.model;card.onclick=()=>{showView('create');setKind(w.kind);showResult(w)}})};
function pendingUI(data,task,message){busy(message);const id=document.createElement('p');id.textContent=task.id?'任务 ID：'+task.id:'未识别到任务 ID，请查看原始响应';$('#previewArea').append(id);rawPanel(data);if(task.id){const b=document.createElement('button');b.textContent='查询 / 继续等待';b.className='media-link';b.onclick=()=>poll(task);$('#previewArea').append(b)}}
function complete(data,task){const media=mediaItems(data,task.kind);if(!media.length)return false;const w={...task,id:Date.now(),taskId:task.id,media,date:new Date().toLocaleString('zh-CN')};record(w);showResult(w);return true}
async function poll(task){if(running)return;running=true;$('#generate').disabled=true;try{const data=await api('/api/task?kind='+task.kind+'&id='+encodeURIComponent(task.id));const d=unwrap(data);if(complete(data,task)){activeTask=null;sessionStorage.removeItem('yunying-task');return}const state=String(d.status||d.state||'').toLowerCase();if(['failed','error','cancelled','canceled','expired'].includes(state))throw new Error(d.error?.message||d.message||'生成任务失败：'+state);pendingUI(data,task,'任务状态：'+(state||'等待平台返回结果'));if(['succeeded','completed','success','done'].includes(state)){toast('任务已完成，但未识别到媒体地址，请查看原始响应');return}if(Date.now()-task.started<20*60*1000)pollTimer=setTimeout(()=>poll(task),5000);else toast('已暂停自动轮询，可手动继续查询')}catch(e){pendingUI({error:e.message},task,'查询暂停');toast(e.message)}finally{running=false;$('#generate').disabled=false}}
$('#generate').onclick=async()=>{if(running)return;const prompt=$('#prompt').value.trim();if(!prompt)return toast('请先输入创作描述');if(location.protocol==='file:')return toast('请启动 start.ps1 并通过 localhost 地址打开');if(activeTask)return toast('当前有未完成任务，请查询结果，或点“放弃等待”后创建新任务');clearTimeout(pollTimer);const task={kind,model:$('#model').value,prompt,style,started:Date.now()};running=true;$('#generate').disabled=true;busy('正在提交'+({video:'视频',image:'图片',music:'音乐'}[kind])+'请求…');try{const data=await api('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...task,prompt:kind==='music'?prompt:prompt+'。画面风格：'+style,duration:parseInt($('#duration').value),ratio:$('#ratio').value.split(' ')[0]})});if(complete(data,task))return;task.id=taskId(data);pendingUI(data,task,'请求已提交');if(task.id){activeTask=task;sessionStorage.setItem('yunying-task',JSON.stringify(task));if(kind==='video')pollTimer=setTimeout(()=>poll(task),300);else toast('音乐任务已提交，查询能力取决于 getState 配置')}}catch(e){busy('提交未完成');const p=document.createElement('p');p.textContent=e.message;$('#previewArea').append(p);toast(e.message)}finally{running=false;$('#generate').disabled=false}};
const abandon=document.createElement('button');abandon.textContent='放弃等待';abandon.className='media-link';abandon.onclick=()=>{clearTimeout(pollTimer);activeTask=null;sessionStorage.removeItem('yunying-task');toast('已停止本地等待，平台任务仍可能执行')};$('.preview-bottom').append(abandon);
try{const t=JSON.parse(sessionStorage.getItem('yunying-task')||'null');if(t?.id){activeTask=t;pendingUI({},t,'存在待查询任务')}}catch{}
