const TC=globalThis.YunyingTasks;
function readSaved(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function saveSaved(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器存储空间不足，请导出并清理旧记录');return false}}
let jobs=TC.recover(readSaved('yunying-jobs',[])),drafts=readSaved('yunying-drafts',{}),jobFilter='全部',workFilter='全部',workQuery='',favoritesOnly=false,musicPolling=false,querying=new Set(),jobTimers=new Map();
const names={video:'视频',image:'图片',music:'音乐'};
const stateNames={submitting:'正在提交',uncertain:'提交结果待确认',pending:'等待生成',polling:'查询中',paused:'等待继续查询',succeeded:'已完成',failed:'生成失败',stopped:'已停止等待',unrecognized:'待检查响应'};
clearTimeout(pollTimer);activeTask=null;
try{const old=JSON.parse(sessionStorage.getItem('yunying-task')||'null');if(old?.id&&!jobs.some(j=>j.id===old.id)){jobs.unshift({...old,uid:'legacy-'+old.id,status:'paused',started:old.started||Date.now()});sessionStorage.removeItem('yunying-task')}}catch{}
function persistJobs(){saveSaved('yunying-jobs',jobs);renderJobs();renderTaskCount()}
function updateJob(job,patch){Object.assign(job,patch,{updated:Date.now()});jobs=TC.upsert(jobs,job);persistJobs()}
const taskNav=document.createElement('button');taskNav.className='nav';taskNav.dataset.view='tasks';taskNav.innerHTML='◷ <span>任务中心</span><small id="taskCount">0</small>';document.querySelector('aside nav').append(taskNav);taskNav.onclick=()=>showView('tasks');
const taskView=document.createElement('section');taskView.id='taskView';taskView.hidden=true;taskView.innerHTML='<div class="section-heading"><h2>任务中心 <span>状态保存在当前浏览器，刷新后可继续查询</span></h2><button id="exportJobs">导出任务记录 ↓</button></div><div class="job-filters"></div><div id="jobList"></div>';
$('#libraryView').after(taskView);
for(const f of ['全部','进行中','已完成','失败与待检查']){const b=document.createElement('button');b.className='filter-button'+(f==='全部'?' selected':'');b.textContent=f;b.onclick=()=>{jobFilter=f;taskView.querySelectorAll('.job-filters button').forEach(x=>x.classList.toggle('selected',x===b));renderJobs()};taskView.querySelector('.job-filters').append(b)}
const priorView=showView;showView=function(view){taskView.hidden=view!=='tasks';if(view==='tasks'){priorView('library');$('#libraryView').hidden=true;intro.hidden=true;$('#title').innerHTML='每一个灵感，<em>都有进展。</em>';$('#crumb').textContent='任务中心';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b===taskNav));renderJobs()}else priorView(view)};
function renderTaskCount(){const n=jobs.filter(j=>['submitting','pending','polling','paused','uncertain'].includes(j.status)).length;$('#taskCount').textContent=n;$('#taskCount').hidden=n===0}
function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#exportJobs').onclick=()=>downloadJSON(jobs,'云映-任务记录.json');
function button(text,action){const b=document.createElement('button');b.textContent=text;b.className='job-button';b.onclick=action;return b}
function inspectJob(job){$('#modalContent').replaceChildren();const h=document.createElement('h2');h.textContent=stateNames[job.status]||job.status;const p=document.createElement('p');p.textContent=job.error||job.prompt;const pre=document.createElement('pre');pre.className='job-raw';pre.textContent=JSON.stringify({taskId:job.id,model:job.model,status:job.status,response:job.response},null,2);$('#modalContent').append(h,p,pre);$('#modal').showModal()}
function renderJobs(){const list=$('#jobList');list.replaceChildren();const filtered=jobs.filter(j=>jobFilter==='全部'||(jobFilter==='进行中'&&['submitting','pending','polling','paused'].includes(j.status))||(jobFilter==='已完成'&&j.status==='succeeded')||(jobFilter==='失败与待检查'&&['failed','uncertain','unrecognized','stopped'].includes(j.status)));if(!filtered.length){const p=document.createElement('p');p.className='empty-note';p.textContent='这里还没有任务。填写描述并点击生成后，任务会出现在这里。';list.append(p);return}for(const job of filtered){const card=document.createElement('article');card.className='job-card';const top=document.createElement('div');top.className='job-top';const h=document.createElement('strong');h.textContent=(names[job.kind]||'创作')+' · '+job.model;const state=document.createElement('span');state.className='job-state '+job.status;state.textContent=stateNames[job.status]||job.status;top.append(h,state);const prompt=document.createElement('p');prompt.className='job-prompt';prompt.textContent=job.prompt;const meta=document.createElement('small');meta.textContent=new Date(job.started).toLocaleString('zh-CN')+(job.id?' · 任务 '+job.id:'')+(job.error?' · '+job.error:'');const actions=document.createElement('div');actions.className='job-actions';if(TC.canQuery(job))actions.append(button(querying.has(job.uid)?'正在查询…':'查询结果',()=>queryJob(job)));if(job.status==='succeeded'){actions.append(button('查看作品',()=>{const w=works.find(w=>w.jobUid===job.uid||(job.id&&w.taskId===job.id));if(w){showView('create');showResult(w)}else toast('本机作品记录已移除，可检查响应中的原始链接')}))}if(job.status==='uncertain')actions.append(button('允许重新提交',()=>allowResubmit(job)));actions.append(button(job.status==='failed'?'修改参数后重试':'复用参数',()=>loadJob(job)),button('详情',()=>inspectJob(job)));if(['pending','polling','paused'].includes(job.status))actions.append(button('停止本地等待',()=>{clearTimeout(jobTimers.get(job.uid));updateJob(job,{status:'stopped'});toast('仅停止本地查询，平台任务未取消')}));if(job.status==='stopped'&&job.id)actions.append(button('重新查询',()=>{job.started=Date.now();updateJob(job,{status:'paused'});queryJob(job)}));card.append(top,prompt,meta,actions);list.append(card)}}
function captureDraft(){drafts[kind]={prompt:$('#prompt').value,model:$('#model').value,style,ratio:$('#ratio').value,duration:$('#duration').value};saveSaved('yunying-drafts',drafts);$('#draftStatus').textContent='草稿已保存 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function restoreDraft(k){const d=drafts[k];if(!d){$('#prompt').value='';$('#chars').textContent='0 / 1200';return}$('#prompt').value=d.prompt||'';$('#chars').textContent=$('#prompt').value.length+' / 1200';if(models[k].includes(d.model))$('#model').value=d.model;if(d.ratio)$('#ratio').value=d.ratio;if(d.duration)$('#duration').value=d.duration;style=d.style||'电影感';document.querySelectorAll('.style').forEach(b=>b.classList.toggle('selected',b.dataset.style===style))}
const draftNote=document.createElement('div');draftNote.className='draft-row';draftNote.innerHTML='<span id="draftStatus">输入内容自动保存为草稿</span><button id="exportDraft">导出描述 ↓</button>';$('.prompt-footer').after(draftNote);
$('#prompt').addEventListener('input',captureDraft);['#model','#ratio','#duration'].forEach(s=>$(s).addEventListener('change',captureDraft));document.querySelectorAll('.style').forEach(b=>b.addEventListener('click',captureDraft));
const priorKind=setKind;setKind=function(k){if(k!==kind){captureDraft();priorKind(k);restoreDraft(k)}else priorKind(k);$('#draftStatus').textContent='各类型草稿独立保存'};
const priorPrompt=setPrompt;setPrompt=function(t){priorPrompt(t);captureDraft()};restoreDraft(kind);
$('#exportDraft').onclick=()=>downloadJSON({kind,...drafts[kind],prompt:$('#prompt').value},'云映-创作草稿.json');
$('#new').onclick=()=>{if(running)return toast('请等待提交请求结束');showView('create');setPrompt('');toast('已新建空白草稿，已有任务保留在任务中心')};
function loadJob(job){if(running)return toast('请等待当前请求结束');showView('create');setKind(job.kind);if(models[kind].includes(job.model))$('#model').value=job.model;if(job.ratio){const o=[...$('#ratio').options].find(o=>o.value.startsWith(job.ratio));if(o)$('#ratio').value=o.value}if(job.duration){const o=[...$('#duration').options].find(o=>parseInt(o.value)===job.duration);if(o)$('#duration').value=o.value}style=job.style||'电影感';document.querySelectorAll('.style').forEach(b=>b.classList.toggle('selected',b.dataset.style===style));setPrompt(job.prompt);toast('已恢复描述和参数，请确认后生成')}
function errorStatus(job,error){const rejected=error.status>=400&&error.status<500&&![408,409].includes(error.status);updateJob(job,{status:job.id?'paused':rejected?'failed':'uncertain',error:TC.errorText(error)});toast(job.error);renderPreview(job)}
function renderPreview(job){if(job.status==='succeeded'){const w=works.find(w=>w.jobUid===job.uid);if(w)showResult(w);return}busy(stateNames[job.status]||'等待生成');const p=document.createElement('p');p.textContent=job.error||(job.id?'任务已提交，可以继续创作其他内容，稍后到任务中心查看结果。':'正在等待平台确认；请勿重复点击提交。');$('#previewArea').append(p);if(job.id){const id=document.createElement('p');id.textContent='任务 ID：'+job.id;$('#previewArea').append(id)}$('#previewArea').append(button('查看任务中心',()=>showView('tasks')));if(job.response)rawPanel(job.response)}
function finishJob(job,data){const media=mediaItems(data,job.kind);if(!media.length)return false;if(job.status==='stopped')return false;updateJob(job,{status:'succeeded',error:null,response:undefined});if(!works.some(w=>w.jobUid===job.uid)){record({...job,id:Date.now(),taskId:job.id,jobUid:job.uid,media,date:new Date().toLocaleString('zh-CN'),name:job.prompt.slice(0,30)})}renderPreview(job);toast(names[job.kind]+'生成完成');return true}
async function queryJob(job){if(querying.has(job.uid)||job.status==='succeeded'||job.status==='failed')return;if(job.kind==='music'&&!musicPolling){toast('音乐查询接口尚未配置，可在详情中查看平台响应');return}clearTimeout(jobTimers.get(job.uid));querying.add(job.uid);updateJob(job,{status:'polling',error:null});try{const data=await api('/api/task?kind='+job.kind+'&id='+encodeURIComponent(job.id));if(job.status==='stopped')return;if(finishJob(job,data))return;const outcome=TC.outcome(data);if(outcome==='failed'){const d=unwrap(data);updateJob(job,{status:'failed',response:data,error:TC.errorText(d.error?.message||d.message||'平台生成失败')});toast(job.error);return}if(outcome==='completed'){updateJob(job,{status:'unrecognized',response:data,error:'平台报告完成，但未识别到媒体地址，请查看详情。'});return}updateJob(job,{status:'pending',response:data});if(Date.now()-job.started<20*60*1000)jobTimers.set(job.uid,setTimeout(()=>queryJob(job),5000));else updateJob(job,{status:'paused',error:'自动查询已暂停，可手动继续。'})}catch(e){errorStatus(job,e)}finally{querying.delete(job.uid);renderJobs()}}
$('#generate').onclick=async()=>{if(running)return;const prompt=$('#prompt').value.trim();if(!prompt)return toast('请先输入创作描述');const pendingSubmit=jobs.some(j=>j.status==='submitting');if(pendingSubmit)return toast('已有请求正在提交，请稍候');const settings={kind,model:$('#model').value,prompt,style,duration:parseInt($('#duration').value),ratio:$('#ratio').value.split(' ')[0]};if(jobs.some(j=>['pending','polling','paused','uncertain'].includes(j.status)&&j.prompt===prompt&&j.model===settings.model))return toast('相同描述已有待确认任务，请先到任务中心查询，避免重复计费');captureDraft();const job={...settings,uid:crypto.randomUUID(),started:Date.now(),status:'submitting'};jobs.unshift(job);persistJobs();running=true;$('#generate').disabled=true;renderPreview(job);try{const data=await api('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...settings,prompt:kind==='music'?prompt:prompt+'。画面风格：'+style})});if(TC.outcome(data)==='failed'){const d=unwrap(data);updateJob(job,{status:'failed',response:data,error:TC.errorText(d.error?.message||d.message||'平台拒绝生成')});renderPreview(job);return}if(finishJob(job,data))return;const id=TC.taskId(data);updateJob(job,{id,response:data,status:id?'pending':'unrecognized',error:id?null:'未识别到任务 ID，请检查平台响应，避免重复提交。'});renderPreview(job);if(id&&(job.kind==='video'||job.kind==='music'&&musicPolling))jobTimers.set(job.uid,setTimeout(()=>queryJob(job),500));else if(job.kind==='music')toast('音乐任务已提交，自动查询尚待平台文档')}catch(e){errorStatus(job,e)}finally{running=false;$('#generate').disabled=false}};
