function persistWorks(){saveSaved('yunying-works',works);$('#count').textContent=works.length;renderLibrary()}
function renameWork(w){$('#modalContent').replaceChildren();const h=document.createElement('h2');h.textContent='修改作品名称';const input=document.createElement('input');input.className='template-search';input.style.width='100%';input.maxLength=60;input.value=w.name||w.prompt?.slice(0,30)||'未命名作品';input.setAttribute('aria-label','作品名称');const b=button('保存名称',()=>{w.name=input.value.trim()||'未命名作品';persistWorks();$('#modal').close()});$('#modalContent').append(h,input,b);$('#modal').showModal()}
function deleteWork(w){$('#modalContent').replaceChildren();const h=document.createElement('h2');h.textContent='删除这条作品记录？';const p=document.createElement('p');p.textContent='只删除当前浏览器中的作品记录，已下载文件和平台任务不受影响。';$('#modalContent').append(h,p,button('确认删除本地记录',()=>{works=works.filter(x=>x!==w);persistWorks();$('#modal').close()}),button('保留',()=>$('#modal').close()));$('#modal').showModal()}
renderLibrary=function(){const list=$('#library');list.replaceChildren();const filtered=works.filter(w=>(workFilter==='全部'||names[w.kind]===workFilter)&&(!favoritesOnly||w.favorite)&&(!workQuery||((w.name||'')+' '+w.prompt).toLowerCase().includes(workQuery)));if(!filtered.length){const p=document.createElement('p');p.className='empty-note';p.textContent=works.length?'没有匹配的作品，试试其他筛选条件。':'生成完成后，作品会自动保存在这里。';list.append(p);return}for(const w of filtered){const card=document.createElement('article');card.className='card work-card';const open=document.createElement('button');open.className='work-open';if(w.kind==='image'&&w.media?.[0]){const img=document.createElement('img');img.src=w.media[0];img.alt=w.name||w.prompt;img.loading='lazy';open.append(img)}else{const cover=document.createElement('div');cover.className='result-art';cover.style.height='150px';const glyph=document.createElement('span');glyph.textContent=w.kind==='music'?'♫':'▷';cover.append(glyph);open.append(cover)}open.onclick=()=>{showView('create');showResult(w)};const body=document.createElement('div');body.className='card-body';const title=document.createElement('strong');title.textContent=w.name||w.prompt?.slice(0,30)||'未命名作品';const meta=document.createElement('p');meta.textContent=(names[w.kind]||'演示')+' · '+(w.model||w.style||'');const actions=document.createElement('div');actions.className='job-actions';actions.append(button(w.favorite?'★ 已收藏':'☆ 收藏',()=>{w.favorite=!w.favorite;persistWorks()}),button('改名',()=>renameWork(w)),button('复用',()=>loadJob(w)),button('删除',()=>deleteWork(w)));body.append(title,meta,actions);card.append(open,body);list.append(card)}};
