const builderButton=button('＋ 描述助手',()=>{if(running)return toast('请等待提交请求结束');$('#modalContent').replaceChildren();const h=document.createElement('h2');h.textContent=names[kind]+'描述助手';const note=document.createElement('p');note.textContent='填写要素后组合到当前描述，不会调用 API 或产生费用。';$('#modalContent').append(h,note);const fields=kind==='music'?['曲风与情绪','乐器与人声','节奏与速度','主题与使用场景']:['主体与动作','环境与时间','镜头与构图','光线与氛围'];const inputs=fields.map(label=>{const l=document.createElement('label');l.className='builder-label';l.textContent=label;const input=document.createElement('input');input.className='builder-input';input.maxLength=180;l.append(input);$('#modalContent').append(l);return {label,input}});const b=button('整理并填入描述',()=>{const segments=inputs.filter(x=>x.input.value.trim()).map(x=>x.label+'：'+x.input.value.trim());if(!segments.length)return toast('至少填写一个要素');const result=[$('#prompt').value.trim(),...segments].filter(Boolean).join('；');if(result.length>1200)return toast('描述超过 1200 字，请先精简内容');setPrompt(result);$('#modal').close()});$('#modalContent').append(b);$('#modal').showModal()});$('.prompt-footer').prepend(builderButton);
function allowResubmit(job){$('#modalContent').replaceChildren();const h=document.createElement('h2');h.textContent='原请求的提交结果尚未确认';const p=document.createElement('p');p.textContent='网络中断不代表平台没有受理。请先到 API 平台检查任务记录；重新提交可能重复生成并重复计费。确认继续会解锁这份描述并恢复草稿，不会立即提交。';$('#modalContent').append(h,p,button('我已检查，解锁并恢复草稿',()=>{updateJob(job,{status:'stopped',error:'用户确认后解锁描述，原平台任务状态仍未知'});$('#modal').close();loadJob(job)}),button('暂不重试',()=>$('#modal').close()));$('#modal').showModal()}

