function explainResponse(data,kind,status){const d=unwrap(data||{}),state=String(d.status||d.state||'').toLowerCase();const descriptions={queued:['已进入队列','平台已收到请求，正在等待可用资源。'],pending:['已进入队列','平台已收到请求，请耐心等待。'],submitted:['提交成功','平台已受理，正在安排生成。'],running:['正在生成','模型正在处理，完成后会出现预览和下载入口。'],processing:['正在生成','模型正在处理，完成后会出现预览和下载入口。'],in_progress:['正在生成','模型正在处理，完成后会出现预览和下载入口。'],succeeded:['平台已完成','正在读取生成结果。'],completed:['平台已完成','正在读取生成结果。'],success:['平台已完成','正在读取生成结果。'],failed:['生成失败','平台未能完成本次生成，可查看原因并调整描述。'],error:['生成失败','平台返回错误，请查看下方说明。'],cancelled:['任务已取消','平台已取消该任务。'],expired:['任务已过期','请到平台查看任务详情。']};
 let [title,message]=descriptions[state]||(['submitting','uncertain'].includes(status)?['等待提交确认','尚未确认平台是否受理，请勿重复提交。']:['请求已受理或待确认','平台没有提供可识别的详细进度，可点击查询结果查看最新状态。']);
 if(status==='succeeded'){title='生成完成';message='作品已保存，可在我的作品中查看。'}
 if(status==='failed'){title='生成失败';message=TC.errorText(d.error?.message||d.message||'请检查描述、模型和账户额度。')}
 if(status==='paused'){title='查询已暂停';message='任务可能仍在平台运行。点击查询结果可继续检查，不会重新提交生成。'}
 if(status==='uncertain'){title='提交结果尚未确认';message='网络可能中断，平台也可能已经受理。请先检查平台记录，避免重复计费。'}
 let progress=null;for(const value of [d.progress,d.progress_percent,d.percentage,d.percent]){if(value===null||value===undefined||value==='')continue;const n=Number(String(value).replace('%',''));if(Number.isFinite(n)&&n>=0&&n<=100){progress=n;break}}
 if(kind==='music'&&!musicPolling&&status!=='succeeded'){message+=' 音乐查询接口尚未配置，暂时无法自动跟踪。'}
 return {title,message,progress,rawState:state};
}
function responseSummary(data,job){const info=explainResponse(data,job.kind,job.status),box=document.createElement('div');box.className='response-summary';const h=document.createElement('strong');h.textContent=info.title;const p=document.createElement('p');p.textContent=job.error?TC.errorText(job.error):info.message;box.append(h,p);if(info.progress!==null){const meter=document.createElement('progress');meter.max=100;meter.value=info.progress;meter.setAttribute('aria-label','平台返回进度');const label=document.createElement('small');label.textContent='平台返回进度：'+info.progress+'%';box.append(meter,label)}else{const small=document.createElement('small');small.textContent='平台未提供百分比进度，不代表任务没有在运行。';box.append(small)}if(job.updated){const time=document.createElement('small');time.textContent='最近查询 / 更新：'+new Date(job.updated).toLocaleTimeString('zh-CN');box.append(time)}return box}
const previousRaw=rawPanel;rawPanel=function(data){const match=jobs.find(j=>j.response===data);const fake=match||{kind,status:'pending'};$('#previewArea').append(responseSummary(data,fake));previousRaw(data);const summary=$('#previewArea details:last-of-type summary');if(summary)summary.textContent='技术详情（可选）'};
const previousInspect=inspectJob;inspectJob=function(job){previousInspect(job);$('#modalContent h2').after(responseSummary(job.response,job))};
const previousJobs=renderJobs;renderJobs=function(){previousJobs();const filtered=jobs.filter(j=>jobFilter==='全部'||(jobFilter==='进行中'&&['submitting','pending','polling','paused'].includes(j.status))||(jobFilter==='已完成'&&j.status==='succeeded')||(jobFilter==='失败与待检查'&&['failed','uncertain','unrecognized','stopped'].includes(j.status)));document.querySelectorAll('#jobList .job-card').forEach((card,i)=>{const job=filtered[i];if(job)card.querySelector('.job-prompt').after(responseSummary(job.response,job))})};
